/** Runs operator-provided argv without a shell and without controller secrets. */
export async function runValidationCommands(cwd, commands, timeoutMs = 10 * 60_000, signal) {
    const deadline = validationDeadline(timeoutMs);
    const env = {};
    for (const name of VALIDATION_ENV) {
        const value = process.env[name];
        if (value !== undefined)
            env[name] = value;
    }
    const results = [];
    for (const argv of commands) {
        const [command, ...args] = argv;
        if (command === undefined)
            throw new Error("Validation command must not be empty");
        const remainingMs = deadline - Date.now();
        if (remainingMs <= 0) {
            results.push({ argv, result: deadlineExceededResult() });
            break;
        }
        const result = await runCommand({
            command,
            args,
            cwd,
            env,
            timeoutMs: remainingMs,
            maxOutputBytes: 2 * 1024 * 1024,
            ...(signal === undefined ? {} : { signal }),
        });
        results.push({ argv, result });
        if (result.exitCode !== 0 || result.timedOut)
            break;
    }
    return results;
}
